choose.when:
(

        e.created_by = #{scope.userId}
        OR e.primary_responsible_user_id = #{scope.userId}
        OR EXISTS (
            SELECT 1 FROM equipment_responsible_person scoped_person
            WHERE scoped_person.tenant_id = e.tenant_id
              AND scoped_person.equipment_id = e.id
              AND scoped_person.user_id = #{scope.userId}
              AND scoped_person.status = 1
              AND scoped_person.deleted = 0
        )


        OR


        e.organization_id IN

            #{organizationId}


)

mapper.sql:
e.tenant_id = #{tenantId}
AND e.deleted = 0
AND 

    AND (
        e.equipment_code LIKE CONCAT('%', #{keyword}, '%')
        OR e.equipment_name LIKE CONCAT('%', #{keyword}, '%')
        OR e.model LIKE CONCAT('%', #{keyword}, '%')
        OR e.asset_number LIKE CONCAT('%', #{keyword}, '%')
        OR e.factory_serial_number LIKE CONCAT('%', #{keyword}, '%')
    )

AND e.category_id = #{categoryId}
AND e.organization_id = #{organizationId}
AND e.location_id = #{locationId}

    AND current_status.status_code = #{currentStatusCode}


    AND e.lifecycle_stage = #{lifecycleStage}

AND e.status = #{status}

mapper.select:
SELECT COUNT(*) FROM equipment
WHERE tenant_id = #{tenantId} AND equipment_code = #{code} AND deleted = 0
AND id != #{excludeId}

mapper.update:
UPDATE equipment
SET deleted = 1, status = 0, updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND version = #{version}
  AND deleted = 0

UPDATE equipment_current_status
SET status_code = #{statusCode}, status_since = #{statusSince},
    reason = #{reason}, source_type = #{sourceType},
    updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND equipment_id = #{equipmentId}
  AND version = #{version}

UPDATE equipment_status_history
SET ended_time = #{endedTime},
    duration_seconds = TIMESTAMPDIFF(SECOND, started_time, #{endedTime})
WHERE tenant_id = #{tenantId}
  AND equipment_id = #{equipmentId}
  AND ended_time IS NULL

UPDATE equipment
SET organization_id = #{request.organizationId},
    location_id = #{request.locationId},
    primary_responsible_user_id = #{request.primaryResponsibleUserId},
    updated_by = #{operatorId},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{equipmentId}
  AND version = #{request.version}
  AND deleted = 0

UPDATE equipment_barcode
SET active_slot = NULL, invalidated_by = #{operatorId},
    invalidated_time = CURRENT_TIMESTAMP(3), invalidation_reason = #{reason}
WHERE tenant_id = #{tenantId}
  AND equipment_id = #{equipmentId}
  AND active_slot = 1
